    "source": "Agência Câmara",
    "sourceUrl": "https://www.camara.leg.br",
    "articleUrl": "https://www.camara.leg.br/noticias/1321312-comissao-aprova-proposta-de-politica-para-pessoas-com-altas-habilidades",
    "publishedAt": "19/11/2026 às 19:40",
